import{c as e,Q as d,j as a,m as r}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"执行状态说明 - 了解已完成、部分完成与等待重试","description":"说明恢复流程中出现的四种终态：completed（已完成）、partial（部分完成）、waiting_to_rerun（等待再次运行）和failed（失败），以及如何在 Arbitrum 上核对交易。","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/zh/execution-status"}],["link",{"rel":"alternate","hreflang":"en","href":"https://hyperliquidrecoverybot.github.io/en/execution-status"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://hyperliquidrecoverybot.github.io/zh/execution-status"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://hyperliquidrecoverybot.github.io/en/execution-status"}],["meta",{"name":"keywords","content":"恢复执行状态, 状态 partial 说明, 交易哈希验证, 找回失败排查"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"执行状态说明 - 了解已完成、部分完成与等待重试"}],["meta",{"property":"og:description","content":"说明恢复流程中出现的四种终态：completed（已完成）、partial（部分完成）、waiting_to_rerun（等待再次运行）和failed（失败），以及如何在 Arbitrum 上核对交易。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/zh/execution-status"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"执行状态说明 - 了解已完成、部分完成与等待重试"}],["meta",{"name":"twitter:description","content":"说明恢复流程中出现的四种终态：completed（已完成）、partial（部分完成）、waiting_to_rerun（等待再次运行）和failed（失败），以及如何在 Arbitrum 上核对交易。"}]]},"headers":[],"relativePath":"zh/execution-status.md","filePath":"zh/execution-status.md","lastUpdated":null}'),i={name:"zh/execution-status.md"};function o(l,t,n,c,h,s){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="执行状态说明" tabindex="-1">执行状态说明 <a class="header-anchor" href="#执行状态说明" aria-label="Permalink to &quot;执行状态说明&quot;">​</a></h1><p>恢复系统分为两层状态：步骤级状态用于展示每一步执行情况，任务级终态用于告诉您整次恢复应如何理解和下一步怎么做。</p><h2 id="任务级终态" tabindex="-1">任务级终态 <a class="header-anchor" href="#任务级终态" aria-label="Permalink to &quot;任务级终态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>终态</th><th>含义</th><th>建议动作</th></tr></thead><tbody><tr><td>completed</td><td>本轮已有实际推进或实际恢复金额，且当前无需立即再次运行</td><td>无需立即再次运行</td></tr><tr><td>partial</td><td>本轮仅完成部分恢复，或本轮没有实际恢复金额但仍存在待处理资产/等待状态</td><td>查看摘要和备注，按需继续处理</td></tr><tr><td>waiting_to_rerun</td><td>本轮已推进成功，但协议等待期/锁定期尚未结束</td><td>到期后再次运行恢复</td></tr><tr><td>failed</td><td>本轮执行被致命错误中断</td><td>先处理错误原因再重试</td></tr></tbody></table><h2 id="步骤级状态" tabindex="-1">步骤级状态 <a class="header-anchor" href="#步骤级状态" aria-label="Permalink to &quot;步骤级状态&quot;">​</a></h2><h2 id="状态总览" tabindex="-1">状态总览 <a class="header-anchor" href="#状态总览" aria-label="Permalink to &quot;状态总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>图标</th><th>含义</th><th>建议动作</th></tr></thead><tbody><tr><td>completed</td><td>✅</td><td>步骤完全成功</td><td>继续等待后续步骤</td></tr><tr><td>completed_partial</td><td>⚠️</td><td>部分成功，部分跳过或失败</td><td>查看备注，必要时重试</td></tr><tr><td>completed_waiting</td><td>⏰</td><td>执行成功但需等待协议周期</td><td>按提示时间再次运行</td></tr><tr><td>skipped_locked</td><td>🔒</td><td>当前资产处于锁定状态</td><td>等待解锁后重试</td></tr><tr><td>skipped_no_assets</td><td>➖</td><td>无可处理资产</td><td>无需操作</td></tr><tr><td>failed_system_error</td><td>❌</td><td>系统异常导致失败</td><td>稍后重试或联系支持</td></tr><tr><td>failed_user_error</td><td>⛔</td><td>用户输入或配置错误</td><td>修正输入后重试</td></tr><tr><td>failed_network_error</td><td>🌐❌</td><td>网络或 RPC 异常</td><td>检查网络后重试</td></tr></tbody></table><h2 id="常见场景解读" tabindex="-1">常见场景解读 <a class="header-anchor" href="#常见场景解读" aria-label="Permalink to &quot;常见场景解读&quot;">​</a></h2><ul><li><code>⚠️ completed_partial</code>：常见于金库或质押中部分资产可处理、部分资产在锁定期。</li><li><code>⏰ completed_waiting</code>：常见于质押流程，操作成功但需等待 1 天或 7 天后继续。</li><li><code>🔒 skipped_locked</code>：当前不代表失败，仅表示资产状态暂不可执行。</li><li>若整轮执行全部为 <code>skipped_*</code> 且没有实际恢复金额，任务级终态会落到 <code>partial</code>，不会显示为 <code>completed</code>。</li></ul><h2 id="如何判断是否需要再次运行" tabindex="-1">如何判断是否需要再次运行 <a class="header-anchor" href="#如何判断是否需要再次运行" aria-label="Permalink to &quot;如何判断是否需要再次运行&quot;">​</a></h2><ul><li>若任务级终态为 <code>waiting_to_rerun</code>，请在对应时间点再次执行恢复。</li><li>若任务级终态为 <code>completed</code>，通常当前阶段无需额外操作。</li><li>若任务级终态为 <code>partial</code>，请先查看上方摘要和剩余问题，再决定是否立即再次运行。</li><li>若步骤中出现 <code>failed_*</code> 且任务级终态为 <code>failed</code>，请先处理错误原因再重试。</li></ul>',11)])])}const _=e(i,[["render",o]]);export{u as __pageData,_ as default};
